import{_ as a,o as e,c as s,a2 as i}from"./chunks/framework.Bqa2y7hU.js";const b=JSON.parse('{"title":"QQ OneBot 11","description":"通过 NapCat / Lagrange / go-cqhttp 等实现端，用反向 WebSocket 接入 OneBot 11。","frontmatter":{"title":"QQ OneBot 11","description":"通过 NapCat / Lagrange / go-cqhttp 等实现端，用反向 WebSocket 接入 OneBot 11。"},"headers":[],"relativePath":"platforms/qq-onebot.md","filePath":"platforms/qq-onebot.md","lastUpdated":1789792423000}'),o={name:"platforms/qq-onebot.md"};function l(n,t,r,h,d,p){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="qq-onebot-11-🔄" tabindex="-1">QQ OneBot 11 🔄 <a class="header-anchor" href="#qq-onebot-11-🔄" aria-label="Permalink to &quot;QQ OneBot 11 🔄&quot;">​</a></h1><p>OneBot 11 不是某个具体程序，而是一套协议。你需要先有一个<strong>实现端</strong>（NapCat、Lagrange、go-cqhttp 等）负责登录 QQ、收发消息，再让它用<strong>反向 WebSocket</strong> 连到 Xiaoyi_QQ_V4。</p><p>这条路的代价是你要自己部署并维护实现端；回报是群管理类能力走 OneBot 标准接口就能用，不受 QQ 开放平台的权限审批限制。</p><h2 id="_1-先部署实现端并登录" tabindex="-1">1. 先部署实现端并登录 <a class="header-anchor" href="#_1-先部署实现端并登录" aria-label="Permalink to &quot;1. 先部署实现端并登录&quot;">​</a></h2><p>在你自己的机器上部署一个 OneBot 11 实现端，选哪个由你决定：</p><table tabindex="0"><thead><tr><th>实现端</th><th>说明</th></tr></thead><tbody><tr><td>NapCat</td><td>常见的 QQ 实现端</td></tr><tr><td>Lagrange</td><td>常见的 QQ 实现端</td></tr><tr><td>go-cqhttp</td><td>老牌实现端</td></tr></tbody></table><p>部署方式、登录方式、扫码 / 滑块验证这些都在实现端自己的文档里，本框架不参与。<strong>先把实现端跑起来、QQ 登录成功</strong>，再往下走。</p><h2 id="_2-在控制台添加机器人" tabindex="-1">2. 在控制台添加机器人 <a class="header-anchor" href="#_2-在控制台添加机器人" aria-label="Permalink to &quot;2. 在控制台添加机器人&quot;">​</a></h2><p>登录控制台，进入「我的机器人」，点「添加机器人」：</p><ul><li>第一步：平台选 <code>qq_onebot</code>（OneBot 11）</li><li>第二步：填机器人的<strong>名称</strong>（只用于你在控制台里区分它），以及可选的 <code>AccessToken</code></li><li>连接方式：选 <strong>反向 WebSocket</strong></li></ul><p>提交后机器人立即上线，不需要重启服务。</p><h2 id="_3-记下反向-ws-地址" tabindex="-1">3. 记下反向 WS 地址 <a class="header-anchor" href="#_3-记下反向-ws-地址" aria-label="Permalink to &quot;3. 记下反向 WS 地址&quot;">​</a></h2><p>创建完成后，控制台会给出一个反向 WS 地址，形如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ws://&lt;你的服务器&gt;:8081/...</span></span></code></pre></div><p>注意这里是 <strong>8081</strong>，不是控制台的 8080。两个端口的用途不同，详见 <a href="/RuaBot.Doc/platforms/callback">回调地址与公网域名</a>。</p><div class="warning custom-block"><p class="custom-block-title">地址在创建后才显示</p><p>这个地址里带有机器的标识信息，请到机器人详情页对照实际显示值复制，不要按上面这行的形状自己拼。</p></div><h2 id="_4-回填到实现端" tabindex="-1">4. 回填到实现端 <a class="header-anchor" href="#_4-回填到实现端" aria-label="Permalink to &quot;4. 回填到实现端&quot;">​</a></h2><p>打开实现端的配置，找到「反向 WebSocket」相关设置：</p><ul><li>把第 3 步复制的地址填进<strong>反向 WS 地址</strong>（不同实现端字段名不一样，认准 reverse / 反向 字样）</li><li>保存并让实现端重连</li></ul><p>如果控制台里这台机器人填了 AccessToken，实现端侧也要填上相同的值，两边一致才能连上。</p><table tabindex="0"><thead><tr><th>控制台字段</th><th>说明</th></tr></thead><tbody><tr><td>AccessToken</td><td>可选。填了就必须和实现端配置一致</td></tr></tbody></table><h2 id="_5-确认在线" tabindex="-1">5. 确认在线 <a class="header-anchor" href="#_5-确认在线" aria-label="Permalink to &quot;5. 确认在线&quot;">​</a></h2><p>回机器人详情页「设置」Tab，确认：</p><ul><li>适配器显示为 <code>qq_onebot</code></li><li>连接方式显示为反向 WebSocket</li><li>状态显示为在线</li></ul><p>状态在线之后，在群里发条消息，机器人的「数据」Tab 里应该能看到消息记录。</p><details class="details custom-block"><summary>截图占位</summary><p>截机器人详情页，露出控制台给出的反向 WS 地址字段（域名可打码成 <code>&lt;你的服务器&gt;</code>），以及「设置」Tab 里的适配器与状态。</p></details><h2 id="_6-能力差异" tabindex="-1">6. 能力差异 <a class="header-anchor" href="#_6-能力差异" aria-label="Permalink to &quot;6. 能力差异&quot;">​</a></h2><p>不同适配器支持的能力不一样，插件里通过能力码（capability）调用时框架会做适配：</p><table tabindex="0"><thead><tr><th>能力</th><th>在 OneBot 11 上</th></tr></thead><tbody><tr><td>按钮消息</td><td>不渲染按钮，需改用文字指令</td></tr><tr><td>Markdown 消息</td><td>不渲染富文本，正文按纯文本发出</td></tr><tr><td>禁言 / 踢人等群管理</td><td>可用，走 OneBot 标准接口</td></tr><tr><td>入群审批</td><td>不可用（QQ 官方专属能力）</td></tr></tbody></table><p>写插件时如果不确定某个能力码在 OneBot 上的表现，可以查 <a href="/RuaBot.Doc/reference/capabilities">平台能力码</a>；机器人在线时，详情页「设置」Tab 底部也会列出它当前支持的能力。</p><h2 id="_7-连不上怎么查" tabindex="-1">7. 连不上怎么查 <a class="header-anchor" href="#_7-连不上怎么查" aria-label="Permalink to &quot;7. 连不上怎么查&quot;">​</a></h2><h3 id="症状-状态一直是离线-控制台没有连接成功的记录" tabindex="-1">症状：状态一直是离线，控制台没有连接成功的记录 <a class="header-anchor" href="#症状-状态一直是离线-控制台没有连接成功的记录" aria-label="Permalink to &quot;症状：状态一直是离线，控制台没有连接成功的记录&quot;">​</a></h3><ul><li><strong>原因</strong>：实现端的反向 WS 地址填错，尤其是端口写成了 8080。</li><li><strong>处理方式</strong>：确认地址里是 <strong>8081</strong>；确认实现端所在机器能访问到框架所在机器的 8081 端口。</li></ul><h3 id="症状-实现端日志报-401-鉴权失败" tabindex="-1">症状：实现端日志报 401 / 鉴权失败 <a class="header-anchor" href="#症状-实现端日志报-401-鉴权失败" aria-label="Permalink to &quot;症状：实现端日志报 401 / 鉴权失败&quot;">​</a></h3><ul><li><strong>原因</strong>：控制台里配了 AccessToken，但实现端没填或填得不一样。</li><li><strong>处理方式</strong>：两边改成完全一致；不需要鉴权时把控制台的 AccessToken 清空、实现端侧也留空。</li></ul><h3 id="症状-连接建立后又立刻断开-反复重连" tabindex="-1">症状：连接建立后又立刻断开，反复重连 <a class="header-anchor" href="#症状-连接建立后又立刻断开-反复重连" aria-label="Permalink to &quot;症状：连接建立后又立刻断开，反复重连&quot;">​</a></h3><ul><li><strong>原因</strong>：网络中间设备掐断长连接，或实现端和框架版本不匹配。</li><li><strong>处理方式</strong>：先看机器人「日志」Tab 里的断开原因；确认实现端是最新版本；检查链路上有没有会中断空闲连接的代理。</li></ul><h3 id="症状-连接正常-但收不到群消息" tabindex="-1">症状：连接正常，但收不到群消息 <a class="header-anchor" href="#症状-连接正常-但收不到群消息" aria-label="Permalink to &quot;症状：连接正常，但收不到群消息&quot;">​</a></h3><ul><li><strong>原因</strong>：QQ 登录掉线，或实现端没订阅对应的上报事件。</li><li><strong>处理方式</strong>：去实现端的界面确认 QQ 仍然在线；确认实现端的事件上报开关是打开的。</li></ul><h3 id="需要抓日志时" tabindex="-1">需要抓日志时 <a class="header-anchor" href="#需要抓日志时" aria-label="Permalink to &quot;需要抓日志时&quot;">​</a></h3><p>优先看机器人详情页的「日志」Tab。要在服务器上看：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux：确认 8081 端口在监听</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lntp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8081</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows：确认 8081 端口在监听</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-NetTCPConnection</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LocalPort </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8081</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">State Listen</span></span></code></pre></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/platforms/callback">回调地址与公网域名</a></li><li><a href="/RuaBot.Doc/platforms/overview">接入方式总览</a></li><li><a href="/RuaBot.Doc/console/bots">我的机器人</a></li></ul>`,45)])])}const k=a(o,[["render",l]]);export{b as __pageData,k as default};
